<?php
require_once __DIR__ . '/includes/auth.php'; requireLogin(); $userId=(int)$_SESSION['user_id']; $pageTitle='Withdrawals'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verifyCsrf($_POST['csrf_token']??null))$error='Your session expired.';else{$amount=(float)post('amount');$method=trim((string)post('method'));$account=trim((string)post('account_details'));if($amount<100)$error='Minimum demo withdrawal is PKR 100.';elseif($method===''||$account==='')$error='Please provide withdrawal details.';elseif(!updateWalletBalance($userId,$amount,'subtract'))$error='Insufficient available balance.';else{$id=nextId('withdrawals');$now=nowIso();collection('withdrawals')->insertOne(['id'=>$id,'user_id'=>$userId,'amount'=>$amount,'payment_method'=>$method,'account_details'=>$account,'status'=>'pending','created_at'=>$now,'reviewed_at'=>null]);addTransaction($userId,'withdrawal',$amount,'Withdrawal request',$id,'pending');collection('wallets')->updateOne(['user_id'=>$userId],['$inc'=>['total_withdrawn'=>$amount]]);flash('success','Withdrawal request submitted.');redirect(appUrl('withdrawals.php'));}}}
$withdrawals=userWithdrawals($userId);$wallet=getUserWallet($userId);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?> - <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">SIMULATED PAYOUT</span><h1>Withdrawals</h1><p class="muted">Available balance: <strong><?=formatCurrency($wallet['balance'])?></strong></p></div><section class="panel narrow-panel"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="form-stack"><?=csrfField()?><label>Amount (PKR)<input type="number" name="amount" min="100" step="0.01" required></label><label>Method<select name="method" required><option value="">Choose method</option><option>JazzCash</option><option>EasyPaisa</option><option>Bank transfer</option></select></label><label>Account details<input name="account_details" maxlength="255" placeholder="Demo account or number" required></label><button class="btn primary full" type="submit">Request withdrawal</button></form></section><section class="panel"><div class="section-heading"><h2>Withdrawal history</h2></div><?php if(!$withdrawals):?><p class="empty">No withdrawal requests yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Amount</th><th>Method</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($withdrawals as $w):?><tr><td><?=formatCurrency($w['amount'])?></td><td><?=e($w['payment_method'])?></td><td><span class="badge <?=e($w['status'])?>"><?=e(ucfirst($w['status']))?></span></td><td><?=e(formatDate($w['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
